# Illustrative only; not the paper's code.
# Token level: a long script contributes many terms, a click very few.
def token_level(steps):
    terms = [tok.ratio * step.advantage for step in steps for tok in step.tokens]
    return mean(terms)

# Step level: each action counts once, however long it is.
def step_level(steps):
    terms = [mean(tok.ratio for tok in step.tokens) * step.advantage for step in steps]
    return mean(terms)
